update activity a join ( select activity_id, count(*) cnt from activity_enrollment where status = 2 and id in
#{id}
group by activity_id ) t on a.id = t.activity_id set a.enrolled_count = a.enrolled_count - t.cnt where a.enrolled_count >= t.cnt
